contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (msg.sender == ownerBefore && newOwner != address(0)) {
            assert(!reverted && c.owner() == newOwner);
        } else {
            assert(reverted && c.owner() == ownerBefore);
        }
    }
}

