contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 stakeAmount, uint256 withdrawAmount) public {
        // Precondition: only stake a positive amount and withdraw no more than staked.
        require(stakeAmount > 0);
        require(withdrawAmount <= stakeAmount);

        // Drive the public entry that creates staked state.
        c.stake(stakeAmount);

        // Read totalSupply through its public view surface.
        uint256 supplyAfterStake = c.totalSupply();

        // Withdraw back down by withdrawAmount (always <= stakeAmount).
        c.withdraw(withdrawAmount, false);

        // Read totalSupply again after the successful withdrawal.
        uint256 supplyAfterWithdraw = c.totalSupply();

        // The aggregate supply must equal total staked minus total withdrawn.
        // This is a general rule over all parameters: totalSupply() must reflect
        // exactly the net staked amount, not merely a trivially constant value.
        assert(supplyAfterStake == stakeAmount && supplyAfterWithdraw == stakeAmount - withdrawAmount);
    }
}

