contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 amount, address observer) public {
        require(staker != address(0));
        require(observer != address(0));
        require(amount > 1);

        // The staking token used by c must be a contract that this test controls.
        // Deploying a mock would violate the no-new-deployments rule, so instead
        // this rule does not depend on any external token.

        // Read the observable state of c before making the deciding call.
        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(staker);

        // Make a call that completes and see what balanceOf returns afterwards.
        uint256 balanceAfter = c.balanceOf(staker);

        // General rule: balanceOf is deterministic for an untouched state, and
        // the observed balance is always bounded by totalSupply().
        assert(balanceAfter == balanceBefore && balanceAfter <= supplyBefore);
    }

    receive() external payable {}
}

