contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, address other) public {
        require(token != address(0), "zero token");
        require(other != address(0), "zero other");
        require(other != token, "same token");

        uint40 lastBefore = c.rewardData(token).lastUpdateTime;
        require(lastBefore == 0, "token already added");

        uint40 lastOtherBefore = c.rewardData(other).lastUpdateTime;

        bool firstReverted;
        try c.addReward(token) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.addReward(token) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        uint40 lastAfter = c.rewardData(token).lastUpdateTime;
        uint40 finishAfter = c.rewardData(token).periodFinish;
        uint40 lastOtherAfter = c.rewardData(other).lastUpdateTime;

        assert(
            !firstReverted &&
            secondReverted &&
            lastAfter == uint40(block.timestamp) &&
            finishAfter == uint40(block.timestamp) &&
            lastOtherAfter == lastOtherBefore
        );
    }

    receive() external payable {}
}

