contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address rewardToken, uint256 amount1, uint256 amount2) public payable {
        require(amount1 > 0 && amount2 > 0);

        // add reward token and notify reward
        c.addReward(rewardToken);
        c.notifyRewardAmount(rewardToken, amount1);

        uint256 rpt1 = c.rewardPerToken(rewardToken);

        // stake some tokens
        c.stakeFor(address(this), amount2);

        uint256 rpt2 = c.rewardPerToken(rewardToken);

        // notify another reward
        c.notifyRewardAmount(rewardToken, amount1);

        uint256 rpt3 = c.rewardPerToken(rewardToken);

        // The reward per token should never decrease after additional rewards are notified
        assert(rpt3 >= rpt2 && rpt2 >= rpt1);
    }
}

