contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address token, uint256 amount, bool addToken, address caller) public payable {
        require(address(this).balance >= 0);

        if (addToken) {
            c.addReward(token);
        }

        uint40 lastUpdateTimeBefore = 0;
        // lastUpdateTime is not public; use the public rewardData getter instead
        (
            uint40 periodFinishBefore,
            uint216 rewardRateBefore,
            uint40 lastUpdateTimeBefore2,
            uint216 rewardPerTokenStoredBefore
        ) = c.rewardData(token);
        lastUpdateTimeBefore = lastUpdateTimeBefore2;

        bool reverted;
        uint256 contractBalanceBefore = address(c).balance;

        // Set the caller via a low-level call so that msg.sender in c is the given address.
        // The test contract can only call as itself, so simulate the caller by using
        // an intermediary: we cannot change msg.sender without cheatcodes.
        // Instead, we only use the test contract as caller. The rule must therefore
        // consider the test contract as the potential distributor.

        // Make the deciding call.
        if (caller == address(this)) {
            try c.notifyRewardAmount(token, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If caller is not the test contract, the call would come from the test contract anyway.
            // To test the distributor check, we use the test contract as caller and require
            // that the reward distributor is not the test contract.
            try c.notifyRewardAmount(token, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // Determine whether the call should revert according to the contract's logic:
        // It reverts if:
        //   - msg.sender != rewardDistributor (msg.sender is address(this))
        //   - amount == 0
        //   - lastUpdateTime == 0 (token not added yet)
        // It succeeds otherwise.

        address distributor = c.rewardDistributor();
        bool isDistributor = (address(this) == distributor);

        // To test the token-added condition, we need to know whether lastUpdateTime was non-zero.
        // The public getter returns lastUpdateTime. If addToken was false and the token was not
        // previously added, lastUpdateTimeBefore == 0.
        // However, if addToken is false but the token was already added in a previous run,
        // lastUpdateTimeBefore may be non-zero. Since the test runs once on a fresh contract,
        // if addToken is false the token is unknown.

        bool tokenKnown;
        if (addToken) {
            tokenKnown = true;
        } else {
            // On a fresh contract, if addToken is false, the token is unknown unless it is address(0)?
            // Actually, if addToken is false, lastUpdateTimeBefore == 0 because the token was never added.
            tokenKnown = (lastUpdateTimeBefore != 0);
        }

        // The call succeeds iff: isDistributor && amount > 0 && tokenKnown
        bool shouldSucceed = isDistributor && (amount > 0) && tokenKnown;

        if (shouldSucceed) {
            assert(!reverted);
        } else {
            assert(reverted);
        }

        // Additional invariants on success:
        if (!reverted) {
            // After successful notifyRewardAmount, contract balance should increase by amount
            // (assuming the reward token is not the staking token and this contract has enough reward tokens).
            // But we cannot easily check balance change because the test contract must have reward tokens.
            // Instead check that periodFinish is in the future and rewardRate is positive.
            (
                uint40 periodFinishAfter,
                uint216 rewardRateAfter,
                uint40 lastUpdateTimeAfter,
                uint216 rewardPerTokenStoredAfter
            ) = c.rewardData(token);
            assert(periodFinishAfter >= block.timestamp);
            assert(periodFinishAfter > periodFinishBefore);
            assert(lastUpdateTimeAfter == block.timestamp);
        }
    }

    receive() external payable {}
}

