        // The test contract is the only account that can interact with c, so we use a low
        // level call to simulate the caller's perspective.
        bool reverted;
        bytes memory data = abi.encodeWithSelector(c.migrateWithdraw.selector, staker, amount);
        (bool success, ) = address(c).call(data);
        reverted = !success;

