        uint256 supplyAfter = c.totalSupply();

        // The call must revert because the caller is not the migrator (migrator is unset).
        assert(reverted == true);

        // The total supply must remain unchanged after the reverting call.
        assert(supplyAfter == supplyBefore);
    }
}

