        // Read the public claimable reward and the paid index through the public surface.
        uint256 cr = c.claimableRewards(account, token);
        uint256 paid = c.userRewardPerTokenPaid(account, token);
        uint256 rpt = c.rewardPerToken(token);

        uint256 earnedVal = c.earned(account, token);

        // When live rewardPerToken equals the stored user-paid index, the earned()
        // formula collapses to the claimable amount (its second term is 0).
        // Note: _earned also subtracts via a uint expression, but the general rule
        // we assert is the additive identity: earned == cr + balance*(rpt-paid)/1e18,
        // which must hold with the balance observable through c.balanceOf(account).
        uint256 bal = c.balanceOf(account);
        uint256 expected = cr + (bal * (rpt - paid)) / 1e18;

        assert(earnedVal == expected);
    }

    receive() external payable {}
}

