contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenSeed, bool useSenderToken, bool useOwnerCall) public {
        // The test contract is the owner and also the caller seen by c (only if useOwnerCall is false it tries a non-owner path).
        address token = useSenderToken ? address(this) : address(uint160(uint256(keccak256(abi.encodePacked(tokenSeed)))));

        uint256 supplyBefore = c.totalSupply();
        uint256 balanceBefore = c.balanceOf(address(this));

        bool reverted;
        if (useOwnerCall) {
            try c.addReward(token) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Calling through an alias is not allowed; instead trade on the fact that c.addReward is external.
            // We can only call through c itself, so the non-owner case is exercised by msg.sender restrictions elsewhere.
            // Here we still call c directly; the owner is this contract, so useOwnerCall true covers the owner path.
            // To keep a decisive assertion we call directly; the revert flag reflects owner+token validity.
            try c.addReward(token) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 supplyAfter = c.totalSupply();
        uint256 balanceAfter = c.balanceOf(address(this));

        bool shouldSucceed = (token != address(0)) && (token != address(this));

        // c is owned by this test contract, so valid tokens with successful call must not revert
        // and must not change totalSupply or the test contract's staking balance.
        assert(supplyBefore == supplyAfter && balanceBefore == balanceAfter && (reverted == !shouldSucceed));
    }

    receive() external payable {}
}

