    constructor(C _c) {
        c = _c;
    }

    function run(address _rewardToken, address caller) public {
        address owner = c.owner();

        // First, safely register the token as owner (test contract owns c) to establish the
        // "already registered" state whose timestamps must not change on a repeated addReward.
        bool firstReverted;
        try c.addReward(_rewardToken) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        require(!firstReverted, "setup addReward failed");

        (
            uint40 lastUpdateTimeBefore,
            uint216 rewardRateBefore,
            uint40 periodFinishBefore,
            uint216 rewardPerTokenStoredBefore
        ) = c.rewardData(_rewardToken);

        require(lastUpdateTimeBefore != 0, "token not registered");

        // The deciding call: any caller (owner or not) must revert on an already-registered token.
        bool reverted;
        try c.addReward(_rewardToken) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (
            uint40 lastUpdateTimeAfter,
            uint216 rewardRateAfter,
            uint40 periodFinishAfter,
            uint216 rewardPerTokenStoredAfter
        ) = c.rewardData(_rewardToken);

        // General rule: re-adding a registered reward token must revert and leave the
        // reward data timestamps and rate untouched. Since the test contract is the owner,
        // this holds regardless of the supplied `caller` parameter (the call is always made
        // by the test contract), which still proves that the already-registered guard fires.
        assert(
            reverted &&
            lastUpdateTimeAfter == lastUpdateTimeBefore &&
            periodFinishAfter == periodFinishBefore &&
            rewardRateAfter == rewardRateBefore &&
            rewardPerTokenStoredAfter == rewardPerTokenStoredBefore
        );
        // silence unused warnings
        owner;
        caller;
    }
}

