contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address staker, uint256 _amount) public {
        require(_amount > 0, "amount must be positive");

        // Only accounts with balance can stake. The test contract itself holds no tokens,
        // so we only check stakeFor's behavior as far as the caller's token balance allows.
        // Read balance before if the call is made by the test contract (address(this))
        // is not useful since it has no tokens. Instead we test the revert rule for an
        // unapproved/non-holder caller, and the success rule via a pre-funded staker.
        //
        // To keep the test simple and observable only through c's public surface, we
        // check the general invariant that stakeFor does not increase balanceOf without
        // a successful transfer, i.e. it must revert for a caller with no tokens.
        //
        // But the property should be about success: when stakeFor succeeds, balanceOf
        // increases by _amount.

        // We cannot guarantee the caller has tokens, so we use a revert-or-complete rule:
        // If stakeFor does not revert, then the staker's balance increased by exactly _amount.

        uint256 beforeBalance = c.balanceOf(staker);

        bool reverted;
        try c.stakeFor(staker, _amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            uint256 afterBalance = c.balanceOf(staker);
            assert(afterBalance == beforeBalance + _amount);
        } else {
            assert(c.balanceOf(staker) == beforeBalance);
        }
    }

    receive() external payable {}
}

