contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address account, address token, uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        c.stakeFor{value: amount}(account, amount);

        uint256 balanceBefore = c.balanceOf(account);
        uint256 claimableBefore = c.claimableRewards(account, token);
        uint256 rpt = c.rewardPerToken(token);

        uint256 earnedValue;
        bool reverted;
        try c.earned(account, token) returns (uint256 v) {
            earnedValue = v;
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted ||
            (earnedValue >= claimableBefore &&
             (balanceBefore == 0 || rpt == 0 || earnedValue < claimableBefore + balanceBefore * rpt))
        );
    }
}

